/// Add a CD to the list.
///
/// # Arguments
/// * `title` - The title of the CD
/// * `author` - The author of the CD
/// * `tracks` - The number of tracks on the CD
/// * `duration` - The duration in minutes
pub fn add_cd(&mut self, title: String, author: String, tracks: u32, duration: u32) {
    self.cd_list.push(CD::new(title, author, tracks, duration));
